#!/usr/bin/env bash
# Bench runner — classy entrypoint for all former shell benches.
# Usage:
#   bash scripts/bench/run.sh vs-bun    # was bench_vs_bun.sh
#   bash scripts/bench/run.sh brutal    # was brutal-bench.sh
#   bash scripts/bench/run.sh jagr      # was run_jagr_benchmark.sh
#   bash scripts/bench/run.sh list
set -euo pipefail
MODE="${1:-list}"
shift || true
SCRIPT_DIR="$(cd "$(dirname "$0")" && pwd)"
REPO_ROOT="$(cd "$SCRIPT_DIR/../.." && pwd)"
cd "$REPO_ROOT"

_run_b64() {
  local b64="$1"
  local tmp
  tmp="$(mktemp -t jhol-bench.XXXXXX)"
  # shellcheck disable=SC2064
  trap 'rm -f "$tmp"' RETURN
  printf '%s' "$b64" | base64 -d > "$tmp"
  chmod +x "$tmp"
  bash "$tmp" "$@"
}

case "$MODE" in
  vs-bun|vs_bun|bun)
    _run_b64 '' "$@"
    ;;
  brutal|brut)
    _run_b64 '' "$@"
    ;;
  jagr|jagr-duel|resolver)
    _run_b64 '' "$@"
    ;;
  list|-h|--help|help)
    cat <<'EOF'
jhol bench runner

Shell modes:
  vs-bun   jhol vs bun (safe, 3-run median)
  brutal   cold/warm install matrix
  jagr     build + JAGR resolver benchmark

Python suites (also runnable directly):
  python3 scripts/bench/versus.py fair|clean|truth|quick|brutal
  python3 scripts/bench/scientific.py [suite|versus]
  python3 scripts/bench/atelier.py
  python3 scripts/bench/jagr_duel.py [compare|simple]
  python3 scripts/bench/workload.py [large|repeat]
  python3 scripts/bench/profiler.py [deep|cold]
EOF
    ;;
  *)
    echo "unknown mode: $MODE (try: list)" >&2
    exit 2
    ;;
esac
